# Self-contained reading view. Escape all research text before allowing the
# limited Markdown link / emphasis markup; no remote code or styles.
def inline(text):
    text = html.escape(text)
    text = re.sub(r'\[([^\]]+)\]\((https://[^\s)]+)\)',r'<a href="\2" target="_blank" rel="noopener noreferrer">\1</a>',text)
    text = re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',text)
    text = re.sub(r'`([^`]+)`',r'<code>\1</code>',text)
    return text

def markdown(text):
    result=[]; para=[]; listed=False
    def flush():
        if para:
            result.append('<p>'+inline(' '.join(para))+'</p>'); para.clear()
    for line in text.splitlines():
        if line.startswith('#'):
            flush()
            if listed: result.append('</ul>'); listed=False
            n=len(line)-len(line.lstrip('#')); label=line[n:].strip()
            section=re.match(r'(\d+)\.',label) if n==2 else None
            anchor=f' id="section-{section.group(1)}"' if section else ''
            result.append(f'<h{n}{anchor}>'+inline(label)+f'</h{n}>')
        elif line.startswith('- '):
            flush()
            if not listed: result.append('<ul>'); listed=True
            result.append('<li>'+inline(line[2:])+'</li>')
        elif not line.strip():
            flush()
            if listed: result.append('</ul>'); listed=False
        else: para.append(line)
    flush()
    if listed: result.append('</ul>')
    return '\n'.join(result)

